CREATE TABLE IF NOT EXISTS station_external_mappings (
 id BIGSERIAL PRIMARY KEY, station_id VARCHAR(255) REFERENCES resort(id) ON DELETE CASCADE, source VARCHAR(32) NOT NULL DEFAULT 'anmsm', external_station_id VARCHAR(255) NOT NULL, verified BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(source, external_station_id));
CREATE TABLE IF NOT EXISTS station_logo_candidates (
 id BIGSERIAL PRIMARY KEY, station_id VARCHAR(255) NOT NULL REFERENCES resort(id) ON DELETE CASCADE, external_station_id VARCHAR(255) NOT NULL, anmsm_media_id VARCHAR(255), anmsm_title TEXT, anmsm_credit TEXT, source_url TEXT NOT NULL, source_checksum VARCHAR(64) NOT NULL, source_format VARCHAR(16) NOT NULL, source_width INTEGER NOT NULL, source_height INTEGER NOT NULL, source_size_bytes INTEGER NOT NULL, optimized_s3_key TEXT, optimized_url TEXT, optimized_width INTEGER, optimized_height INTEGER, optimized_size_bytes INTEGER, content_width INTEGER, content_height INTEGER, aspect_ratio DOUBLE PRECISION, visual_occupancy_width DOUBLE PRECISION, visual_occupancy_height DOUBLE PRECISION, warnings TEXT NOT NULL DEFAULT '[]', status VARCHAR(16) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','ignored','updated','error')), detected_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), checked_at TIMESTAMPTZ, approved_at TIMESTAMPTZ, approved_by BIGINT REFERENCES admin_users(id) ON DELETE SET NULL, ignored_at TIMESTAMPTZ, ignored_by BIGINT REFERENCES admin_users(id) ON DELETE SET NULL, previous_logo_url TEXT, previous_logo_s3_key TEXT, error_code VARCHAR(64), error_message TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(station_id, source_checksum));
CREATE INDEX IF NOT EXISTS station_logo_candidates_status_idx ON station_logo_candidates(status);
